}

/* ================= telegram demo: auto simulation, watch-it-happen ================= */
const chatLog = document.getElementById('chatLog');
const tgStatus = document.getElementById('tgStatus');

const CHECK_TEAL = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#56EDD6" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>';
const DBL_CHECK = '<svg width="15" height="11" viewBox="0 0 20 12" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M1 6.5L4.5 10 11 2.5"/><path d="M8 6.5L11.5 10 18 2.5"/></svg>';
const DOC_ICON = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H7a2 2 0 00-2 2v16a2 2 0 002 2h10a2 2 0 002-2V7z"/><path d="M14 2v5h5"/></svg>';

let demoStarted = false;
let demoGen = 0;
let msgClock = null;

function wait(ms){ return new Promise(res=>setTimeout(res, ms)); }
function step(gen){ if (gen !== demoGen) throw new Error('stale'); }
async function waitVisible(gen){
  step(gen);
  while (current !== 1){ await wait(400); step(gen); }
}

function fmtTime(){
  if (!msgClock) return '';
  const t = msgClock.h.toString() + ':' + (msgClock.m<10?'0':'') + msgClock.m;
  msgClock.m += 1;
  if (msgClock.m>59){ msgClock.m=0; msgClock.h=(msgClock.h+1)%24; }
  return t;
}

function scrollLog(){ chatLog.scrollTop = chatLog.scrollHeight; }

function bubble(who, html, withStamp){
  const row = document.createElement('div');
  row.className = 'msg-row ' + who;
  const b = document.createElement('div');
  b.className = 'bubble';
  b.innerHTML = html;
  if (withStamp){
    const st = document.createElement('div');
    st.className = 'stamp';
    st.innerHTML = (who==='me' ? DBL_CHECK : '') + '<span>' + fmtTime() + '</span>';
    b.appendChild(st);
  }
  row.appendChild(b);
  chatLog.appendChild(row);
  scrollLog();
  return row;
}

function docHtml(name){
  const kind = name.split('.').pop().toUpperCase();
  return '<div class="doc"><div class="doc-ic">' + DOC_ICON + '</div><div><div class="doc-name">' + name + '</div><div class="doc-kind">' + kind + '</div></div></div>';
}

function typingOn(){
  tgStatus.textContent = 'typing…';
  tgStatus.classList.add('typing');
  const row = document.createElement('div');
  row.className = 'msg-row bot typing-row';
  row.innerHTML = '<div class="bubble typing-bubble"><i></i><i></i><i></i></div>';
  chatLog.appendChild(row);
  scrollLog();
  return row;
}
function typingOff(row){
  tgStatus.textContent = 'online';
  tgStatus.classList.remove('typing');
  if (row && row.parentNode) row.remove();
}

async function botSays(gen, html, quick){
  await waitVisible(gen);
  const t = typingOn();
  await wait(quick ? 650 : 1050);
  step(gen);
  typingOff(t);
  return bubble('bot', html, true);
}

async function playScenario(gen, idx){
  const sc = SC()[idx];
  msgClock = { h: sc.base[0], m: sc.base[1] };
  for (const m of sc.msgs){
    await waitVisible(gen);
    if (m.who==='me'){
      await wait(650); step(gen);
      bubble('me', m.text + (m.file ? docHtml(m.file) : ''), true);
    } else {
      const t = typingOn();
      await wait(1000); step(gen);
      typingOff(t);
      bubble('bot', (m.file ? docHtml(m.file) : '') + m.text, true);
    }
    /* reading pause: let the reader read the message, but keep the rhythm brisk */
    const readMs = Math.min(2500, 700 + m.text.length * 30);
    await wait(readMs); step(gen);
  }
  /* receipt as a telegram-style bot message */
  await wait(500); step(gen);
  const t = typingOn();
  await wait(800); step(gen);
  typingOff(t);
  let html = '<div class="receipt-head">' + CHECK_TEAL + '<span>' + sc.receipt.title + '</span></div>';
  sc.receipt.rows.forEach(r=>{ html += '<div class="receipt-row">' + CHECK_TEAL + '<span>' + r + '</span></div>'; });
  bubble('bot', html, true);
}

async function fadeClear(gen){
  chatLog.style.transition = 'opacity .45s ease';
  chatLog.style.opacity = '0';
  await wait(480); step(gen);
  chatLog.innerHTML = '';
  chatLog.style.opacity = '1';
}

async function runLoop(gen){
  try {
    await wait(500);
    while (true){
      await botSays(gen, T().demoGreeting);
      await wait(1600);
      for (let i = 0; i < SC().length; i++){
        await playScenario(gen, i);
        await wait(2600); step(gen);
        if (i < SC().length - 1){ await fadeClear(gen); }
      }
      await botSays(gen, T().demoClosing, true);
      await wait(5200); step(gen);
      await fadeClear(gen);
    }
  } catch(e){ /* stale generation: a newer run owns the stage */ }
}

function restartDemo(){
  demoGen++;
  chatLog.innerHTML = '';
  chatLog.style.opacity = '1';
  tgStatus.textContent = 'online';
  tgStatus.classList.remove('typing');
  if (demoStarted) runLoop(demoGen);
}

function demoEnter(){
  if (demoStarted) return;
  demoStarted = true;
  runLoop(++demoGen);
}

applyLang();
</script>
</body>
</html>

